/** Original bounded UDIF reader: raw, zero/ignored, ADC and zlib runs. No mounting or Apple code. */
public final class DmgConverter {
 private static final class Table{final long first,count,crc;final boolean verify;final CRC32 actual=new CRC32();Table(long f,long n,long c,boolean v){first=f;count=n;crc=c;verify=v;}}
 private static final class Run{long start,size,offset,length,type;Table table;}
 private static final class Plan{long size;List<Run> runs=new ArrayList<>();List<Table> tables=new ArrayList<>();}
 private static long u32(byte[] b,int at){long n=0;for(int i=0;i<4;i++)n=(n<<8)|(b[at+i]&255);return n;}
 private static long u64(byte[] b,int at)throws IOException{long n=0;for(int i=0;i<8;i++)n=(n<<8)|(b[at+i]&255);if(n<0)throw new IOException("DMG_BOUNDS");return n;}
 private static boolean magic(byte[] b,int at,String value){for(int i=0;i<value.length();i++)if((b[at+i]&255)!=value.charAt(i))return false;return true;}
 private static void bounds(long at,long n,long end)throws IOException{if(at<0||n<0||at>end||n>end-at)throw new IOException("DMG_BOUNDS");}
 private static byte[] base64(String text)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();int bits=0,value=0,pad=0,chars=0;boolean ended=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(Character.isWhitespace(c))continue;if(c=='='){pad++;ended=true;if(pad>2)throw new IOException("DMG_PLIST");continue;}int n=c>='A'&&c<='Z'?c-'A':c>='a'&&c<='z'?c-'a'+26:c>='0'&&c<='9'?c-'0'+52:c=='+'?62:c=='/'?63:-1;if(n<0||ended)throw new IOException("DMG_PLIST");chars++;value=(value<<6)|n;bits+=6;if(bits>=8){bits-=8;out.write((value>>bits)&255);if(out.size()>8*1024*1024)throw new IOException("DMG_BOUNDS");}}if((chars+pad)%4!=0||bits!=pad*2||(bits>0&&(value&((1<<bits)-1))!=0))throw new IOException("DMG_PLIST");return out.toByteArray();}
 private static Plan plan(OpticalImage.Source source,long limit)throws IOException{
  if(source.size()<512||source.size()>ImageContainers.MAX+ImageContainers.MAX/16||limit<1||limit>ImageContainers.MAX)throw new IOException("CONVERT_LIMIT");byte[] footer=new byte[512];source.read(source.size()-512,footer,0,512);
  if(!magic(footer,0,"koly")||u32(footer,4)!=4||u32(footer,8)!=512)throw new IOException("DMG_HEADER");if(u64(footer,16)!=0||u32(footer,56)>1||u32(footer,60)>1)throw new IOException("DMG_UNSUPPORTED");
  long fork=u64(footer,24),forkSize=u64(footer,32),xmlAt=u64(footer,216),xmlSize=u64(footer,224),sectors=u64(footer,492);bounds(fork,forkSize,source.size()-512);bounds(xmlAt,xmlSize,source.size()-512);if(xmlSize<1||xmlSize>8*1024*1024||sectors<1||sectors>limit/512||xmlAt<fork+forkSize)throw new IOException("DMG_BOUNDS");
  byte[] xml=new byte[(int)xmlSize];source.read(xmlAt,xml,0,xml.length);String text=new String(xml,StandardCharsets.UTF_8);if(text.contains("<!ENTITY")||text.contains("<!["))throw new IOException("DMG_PLIST");int d=text.indexOf("<!DOCTYPE");if(d>=0){int end=text.indexOf('>',d);if(end<0||text.substring(d,end).indexOf('[')>=0)throw new IOException("DMG_PLIST");text=text.substring(0,d)+text.substring(end+1);}
  final List<byte[]> blocks=new ArrayList<>();
  try{SAXParserFactory factory=SAXParserFactory.newInstance();factory.setNamespaceAware(false);XMLReader reader=factory.newSAXParser().getXMLReader();reader.setEntityResolver((publicId,systemId)->new InputSource(new StringReader("")));reader.setContentHandler(new DefaultHandler(){int depth,nodes;boolean key,data;String last="";StringBuilder value=new StringBuilder();public void startElement(String uri,String local,String name,Attributes attrs)throws SAXException{if(++depth>32||++nodes>100000)throw new SAXException("limit");key=name.equals("key");data=name.equals("data")&&last.equals("Data");if(key||data)value.setLength(0);}public void characters(char[] c,int at,int n)throws SAXException{if(key||data){if(value.length()>12*1024*1024-n)throw new SAXException("limit");value.append(c,at,n);}}public void endElement(String uri,String local,String name)throws SAXException{if(name.equals("key")){last=value.toString();key=false;}if(name.equals("data")&&data){try{byte[] b=base64(value.toString());if(b.length>=4&&magic(b,0,"mish")){if(blocks.size()>=1024)throw new IOException("DMG_BOUNDS");blocks.add(b);}}catch(IOException e){throw new SAXException(e);}data=false;}depth--;}});reader.parse(new InputSource(new StringReader(text)));}catch(Exception e){throw new IOException("DMG_PLIST",e);}
  Plan plan=new Plan();plan.size=sectors*512;for(byte[] b:blocks){if(b.length<204||u32(b,4)!=1)throw new IOException("DMG_HEADER");long first=u64(b,8),count=u64(b,16),data=u64(b,24),runs=u32(b,200);if(first>sectors||count>sectors-first||runs<1||runs>100000||runs>(b.length-204)/40||b.length!=204+runs*40||plan.runs.size()+runs>100000)throw new IOException("DMG_BOUNDS");long checksumType=u32(b,64),checksumBits=u32(b,68);if(checksumType!=0&&(checksumType!=2||checksumBits!=32))throw new IOException("DMG_UNSUPPORTED");Table table=new Table(first*512,count*512,u32(b,72),checksumType==2);plan.tables.add(table);boolean terminated=false;
   for(int i=0;i<runs;i++){int at=204+i*40;long type=u32(b,at),relative=u64(b,at+8),n=u64(b,at+16),offset=u64(b,at+24),packed=u64(b,at+32);if(type==0xffffffffL){if(i!=runs-1||n!=0)throw new IOException("DMG_BOUNDS");terminated=true;continue;}if(type==0x7ffffffeL){if(n!=0)throw new IOException("DMG_BOUNDS");continue;}if(type!=0&&type!=1&&type!=2&&type!=0x80000004L&&type!=0x80000005L)throw new IOException("DMG_UNSUPPORTED");if(n<1||relative>count||n>count-relative)throw new IOException("DMG_BOUNDS");Run run=new Run();run.type=type;run.start=(first+relative)*512;run.size=n*512;run.table=table;if(type==1||type==0x80000004L||type==0x80000005L){bounds(data,offset,forkSize);bounds(data+offset,packed,forkSize);if(packed<1||type==1&&packed!=run.size)throw new IOException("DMG_BOUNDS");run.offset=fork+data+offset;run.length=packed;}else if(packed!=0)throw new IOException("DMG_BOUNDS");plan.runs.add(run);}
   if(!terminated)throw new IOException("DMG_BOUNDS");
  }
  Collections.sort(plan.runs,(a,b)->Long.compare(a.start,b.start));long end=0;for(Run r:plan.runs){if(r.start!=end||r.size>plan.size-end)throw new IOException("DMG_BOUNDS");end+=r.size;}if(end!=plan.size)throw new IOException("DMG_BOUNDS");return plan;
 }
 public static long budget(OpticalImage.Source source,long limit,DiskTools.Progress p)throws IOException{Plan plan=plan(source,limit);decode(source,plan,null,p);return plan.size;}
 public static ImageContainers.Result convert(OpticalImage.Source source,OutputStream out,long limit,DiskTools.Progress p)throws IOException{return decode(source,plan(source,limit),out,p);}
 private static ImageContainers.Result decode(OpticalImage.Source source,Plan plan,OutputStream out,DiskTools.Progress p)throws IOException{
  MessageDigest hash;try{hash=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException e){throw new AssertionError(e);}byte[] input=new byte[65536],output=new byte[65536],zero=new byte[65536];long done=0;
  for(Run r:plan.runs){long produced=0,read=0;Inflater inflater=r.type==0x80000005L?new Inflater():null;AdcInputStream adc=r.type==0x80000004L?new AdcInputStream(new InputStream(){long at;final byte[] buffer=new byte[65536];int pos,end;public int read()throws IOException{if(pos==end){if(at==r.length)return -1;end=(int)Math.min(buffer.length,r.length-at);source.read(r.offset+at,buffer,0,end);at+=end;pos=0;}return buffer[pos++]&255;}}):null;try{while(produced<r.size||(inflater!=null&&!inflater.finished())){p.update(done,plan.size);int n;if(adc!=null){n=adc.read(output,0,(int)Math.min(output.length,r.size-produced));if(n<1)throw new IOException("DMG_DATA");}else if(inflater!=null){if(inflater.needsInput()){if(read==r.length)throw new IOException("DMG_DATA");int count=(int)Math.min(input.length,r.length-read);source.read(r.offset+read,input,0,count);read+=count;inflater.setInput(input,0,count);}try{n=inflater.inflate(output);}catch(DataFormatException e){throw new IOException("DMG_DATA",e);}if(n==0){if(inflater.finished())break;if(inflater.needsInput())continue;throw new IOException("DMG_DATA");}}else{n=(int)Math.min(output.length,r.size-produced);if(r.type==1)source.read(r.offset+produced,output,0,n);else System.arraycopy(zero,0,output,0,n);}if(n>r.size-produced)throw new IOException("DMG_DATA");if(out!=null)out.write(output,0,n);hash.update(output,0,n);r.table.actual.update(output,0,n);produced+=n;done+=n;}
   if(adc!=null&&adc.read()!=-1)throw new IOException("DMG_DATA");if(produced!=r.size||inflater!=null&&(!inflater.finished()||read!=r.length||inflater.getRemaining()!=0))throw new IOException("DMG_DATA");}finally{if(inflater!=null)inflater.end();}}
  for(Table t:plan.tables)if(t.verify&&t.actual.getValue()!=t.crc)throw new IOException("DMG_CHECKSUM");if(out!=null)out.flush();p.update(done,plan.size);return new ImageContainers.Result(done,hash.digest());
 }
}
